 dict(id='F_ACK_QUEUED',meaning='A local append path has queued a MsgAppResp for the indicated index; it has not thereby persisted entries or delivered support.',identity={'node':'response From','recipient':'response To','term':'response Term','index':'response Index'},validity_context='The local raft state when send queues the response; successful follower append or leader self append.',representation=['raft.msgsAfterAppend MsgAppResp'],durability='Volatile queued work. Legal delivery depends on the Ready/storage contract.',recovery='Queued messages are not recovered as messages; restart reconstructs protocol state and can regenerate replies.',source_ids=['S_RESET','S_FOLLOWER_LOG','S_SEND','S_STORAGE_MSG'],unknowns=['No execution has established a concrete durable write or message delivery.']),
